import { daysBetween } from "./dates.mjs";

const GRACE_DAYS = 2;
const CENTS_PER_DAY = 25;
const CAP_CENTS = 1000;

export function finesFor(store, memberId, asOf) {
  return store.loans
    .filter((l) => l.memberId === memberId)
    .map((l) => {
      const daysLate = daysBetween(l.due, l.returned ?? asOf) - GRACE_DAYS;
      return { loanId: l.id, bookId: l.bookId, daysLate, amount: Math.min(daysLate * CENTS_PER_DAY, CAP_CENTS) / 100 };
    })
    .filter((f) => f.daysLate > 0)
    .sort((a, b) => (a.loanId < b.loanId ? -1 : a.loanId > b.loanId ? 1 : 0));
}

export function memberBalance(store, memberId, asOf) {
  const fines = finesFor(store, memberId, asOf).reduce((s, f) => s + Math.round(f.amount * 100), 0);
  const paid = store.payments.filter((p) => p.memberId === memberId).reduce((s, p) => s + Math.round(p.amount * 100), 0);
  return (fines - paid) / 100;
}

export function payFine(store, memberId, amount, date) {
  store.payments.push({ memberId, amount, date });
  return memberBalance(store, memberId, date);
}
