// Hold queue operations. Holds live in store.holds, in placement order.
import { getBook, getMember } from "./store.mjs";

export function placeHold(store, bookId, memberId, date) {
  if (!getBook(store, bookId)) throw new Error("no such book");
  if (!getMember(store, memberId)) throw new Error("no such member");
  if (store.holds.some((h) => h.bookId === bookId && h.memberId === memberId)) throw new Error("already holding");
  const hold = { id: `h${store.nextId++}`, bookId, memberId, date };
  store.holds.push(hold);
  return hold;
}

export function cancelHold(store, holdId) {
  const i = store.holds.findIndex((h) => h.id === holdId);
  if (i >= 0) store.holds.splice(i, 1);
}

export const holdsFor = (store, bookId) => store.holds.filter((h) => h.bookId === bookId);
